/**
 * ════════════════════════════════════════════════════════════════════════════
 *  GERÇEK MOTOR VERİSİ — MODEL → MOTOR
 * ════════════════════════════════════════════════════════════════════════════
 *
 *  KAYNAK: Kullanıcının sağladığı katalog ekran görüntüleri (2026-08).
 *  Ürün adetleri alınmamıştır.
 *
 *  ⚠ MOTOR KODU YOK
 *  Kaynak ekranlarda üretici motor kodu (CHZB, N47D20…) GÖRÜNMÜYOR. Bu yüzden
 *  `engine_codes` boş kalır ve içe aktarmada 1. adım (motor_kodu ile birebir
 *  eşleştirme) bu motorlar için çalışmaz. Eşleştirme 2. adıma düşer:
 *  marka + model + normalize edilmiş MOTOR ADI. Bu nedenle motor adları
 *  kaynaktaki yazımla, HARFİ HARFİNE korunur — "düzeltmek" eşleştirmeyi bozar.
 *
 *  ⚠ HACİM YAKLAŞIKTIR
 *  Ekranda pazarlama hacmi var ("1.9"), gerçek silindir hacmi değil (1910 cc).
 *  `displacement_cc` bu etiketten üretilir (1.9 → 1900). Hacme dayalı
 *  eşleştirme bu yüzden ıskalayabilir; ıskalaması YANLIŞ EŞLEŞMEDEN iyidir.
 *
 *  ⚠ YIL ARALIĞI YOK — `year_from` / `year_to` boş bırakılır.
 *
 *  Model anahtarı, `arac-agaci.ts` içindeki model ADIDIR (slug değil) —
 *  gözle karşılaştırılabilsin diye. Senkron betiği adı slug'a çevirir ve
 *  eşleşmeyen model adı bulursa yüksek sesle uyarır.
 */

export type VehicleFuel = 'DIZEL' | 'BENZIN' | 'LPG' | 'HIBRIT' | 'ELEKTRIK' | 'CNG'

/**
 * Motor girdisi. Yakıt tipi addaki anahtar kelimeden çıkarılır; çıkarılamıyorsa
 * nesne biçimi kullanılarak AÇIKÇA yazılır. Betik, yakıtı belirlenemeyen bir
 * motor bulursa hata verip durur — sessizce "BENZIN" varsaymaz.
 */
export type RealEngine = string | { name: string; fuel: VehicleFuel }

/**
 * Ada bakarak yakıt tipi çıkarımı. SIRA ÖNEMLİDİR.
 *
 * TEMEL YAKIT ÖNCELİKLİDİR: "40 TDI Mild Hybrid" bir DİZELDİR; 48V destekli
 * olması yakıtını değiştirmez ve yakıt filtresi ihtiyacını ortadan kaldırmaz.
 * Bu yüzden TDI/TFSI gibi temel yakıt anahtarları hibritten ÖNCE bakılır ve
 * HİBRİT en sonda, yalnızca temel yakıtı belli etmeyen adlarda (ör. Alfa
 * "1.3 Hybrid") devreye girer. Aksi hâlde dizel bir araç "hibrit" diye
 * sınıflanıp yakıt filtresi aramasının dışında kalabilirdi.
 */
const FUEL_KEYWORDS: Array<{ fuel: VehicleFuel; words: string[] }> = [
  { fuel: 'CNG', words: ['G-TRON', 'GTRON'] },
  { fuel: 'ELEKTRIK', words: ['ELECTRIC', 'E-TRON', 'EV6', 'IONIQ 5', 'PURE ELECTRIC'] },
  {
    fuel: 'DIZEL',
    words: [
      'JTD',
      'JTDM',
      'MULTIJET',
      'VGT-D',
      'TDI',
      'TDCI',
      'HDI',
      'BLUEHDI',
      'CDI',
      'BLUETEC',
      'DCI',
      'CRDI',
      'CDTI',
      'DTI',
      'D-4D',
      'SDI',
      'TDCI',
      'DDIS',
      'BLUE DCI',
      'D4D',
      'CRDT',
      'JTD 16V',
    ],
  },
  {
    fuel: 'BENZIN',
    words: [
      'T.SPARK',
      'TWIN SPARK',
      'MULTIAIR',
      'TSI',
      'TFSI',
      'MPI',
      'FSI',
      'GDI',
      'VVT',
      'VTEC',
      'THP',
      'PURETECH',
      'ECOBOOST',
      'TCE',
      'TGI',
      'TB ',
      'VALVETRONIC',
      'SKYACTIV-G',
      'T-GDI',
      'MIVEC',
    ],
  },
  // Son çare: temel yakıtı belli olmayan adlar
  { fuel: 'HIBRIT', words: ['HYBRID', 'HEV', 'PHEV', 'E-TECH', 'TFSIE', 'TFSI E'] },
]

export function deriveFuel(name: string): VehicleFuel | null {
  const upper = name.toUpperCase()
  for (const group of FUEL_KEYWORDS) {
    if (group.words.some((w) => upper.includes(w))) return group.fuel
  }
  return null
}

/**
 * BMW motor adlarında yakıt, ada bakılarak ÇIKARILAMAZ: "320d" ile "320i"
 * arasındaki tek fark bir harftir ve FUEL_KEYWORDS'teki hiçbir kelimeye
 * uymaz. Bu yüzden BMW'nin her motoru AÇIKÇA etiketlenir.
 *
 * TEMEL YAKIT ÖNCELİĞİ burada da geçerlidir (dosya başındaki nota bakınız):
 *  • "520d Mild-Hybrid" bir DİZELDİR — 48V desteği yakıt filtresi ihtiyacını
 *    ortadan kaldırmaz.
 *  • "530e", "320e", "545e", "25e", "30eX" ve "530eiPerformance" şarj edilebilir
 *    hibrittir ama ALTINDAKİ MOTOR BENZİNLİDİR; BENZIN etiketlenir ki benzinli
 *    filtre aramalarının dışında kalmasınlar.
 *  • "320xd" (xDrive dizel) ve "320tdcompact(Turbodiesel)" adında 'i' geçmez;
 *    ikisi de dizeldir.
 *  • "iX1 30" TAM ELEKTRİKLİDİR (yakıt filtresi yok) — 'i' ile bitmesine
 *    aldanıp benzin sayılmamalı.
 *
 *  ⚠ 3 GT (F34) motorları önce ekran görüntüsünden "GranTurismo" diye
 *  girilmişti; kaynağın HTML'i "GranTourismo" yazıyor. Tarayıcıdan çekim
 *  sırasında 11 motor adı eşleşmeyince yakalandı ve kaynağa göre düzeltildi.
 *  Motor adı ürün eşleştirmesinin anahtarı olduğu için harfi harfine önemli.
 */
const dz = (name: string): RealEngine => ({ name, fuel: 'DIZEL' })
const bz = (name: string): RealEngine => ({ name, fuel: 'BENZIN' })
const el = (name: string): RealEngine => ({ name, fuel: 'ELEKTRIK' })
const cng = (name: string): RealEngine => ({ name, fuel: 'CNG' })

